#include <stdio.h>

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    long long dp[7];
    for (int i = 1; i <= 6; i++) dp[i] = -1;

    for (int i = 0; i < N; i++) {
        int A, B, C, D, E, F;
        scanf("%d %d %d %d %d %d", &A, &B, &C, &D, &E, &F);

        int opp[7] = {0};
        opp[A] = F; opp[F] = A;
        opp[B] = D; opp[D] = B;
        opp[C] = E; opp[E] = C;

        int w[7] = {0};
        for (int b = 1; b <= 6; b++) {
            int top = opp[b];
            int mx = 0;
            for (int v = 1; v <= 6; v++) {
                if (v != b && v != top && v > mx) {
                    mx = v;
                }
            }
            w[b] = mx;
        }

        long long ndp[7];
        for (int j = 1; j <= 6; j++) ndp[j] = -1;

        if (i == 0) {
            for (int b = 1; b <= 6; b++) {
                int top = opp[b];
                if (w[b] > ndp[top]) ndp[top] = w[b];
            }
        } else {
            for (int p = 1; p <= 6; p++) {
                if (dp[p] >= 0) {
                    int top = opp[p];
                    long long val = dp[p] + w[p];
                    if (val > ndp[top]) ndp[top] = val;
                }
            }
        }

        for (int j = 1; j <= 6; j++) dp[j] = ndp[j];
    }

    long long ans = 0;
    for (int j = 1; j <= 6; j++) {
        if (dp[j] > ans) ans = dp[j];
    }

    printf("%lld\n", ans);
    return 0;
}
